package com.ecommerce.order; import com.ecommerce.cart.*; import com.ecommerce.inventory.*; import com.ecommerce.payment.*; import com.ecommerce.user.*; import com.ecommerce.common.ApiException; import org.springframework.transaction.annotation.Transactional; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/v1/orders") public class OrderController {private final CartRepository carts;private final UserRepository users;private final OrderRepository orders;private final InventoryRepository inventory;private final PaymentRepository payments;public OrderController(CartRepository c,UserRepository u,OrderRepository o,InventoryRepository i,PaymentRepository p){carts=c;users=u;orders=o;inventory=i;payments=p;}
@PostMapping @Transactional public Map<String,Object> checkout(Authentication a,@RequestHeader(value="Idempotency-Key",required=false)String idem){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();Cart c=carts.findByUserId(u.getId()).orElseThrow(()->new ApiException("Cart is empty"));if(c.getItems().isEmpty())throw new ApiException("Cart is empty");Order o=new Order();o.setUser(u);o.setStatus(Order.Status.PAYMENT_PENDING);BigDecimal total=BigDecimal.ZERO;for(CartItem ci:c.getItems()){var inv=inventory.findForUpdate(ci.getProduct().getId()).orElseThrow(()->new ApiException("Inventory missing for "+ci.getProduct().getName()));if(inv.getAvailableQuantity()<ci.getQuantity())throw new ApiException("Insufficient inventory for "+ci.getProduct().getName());inv.setAvailableQuantity(inv.getAvailableQuantity()-ci.getQuantity());inv.setReservedQuantity(inv.getReservedQuantity()+ci.getQuantity());OrderItem oi=new OrderItem();oi.setOrder(o);oi.setProduct(ci.getProduct());oi.setSeller(ci.getProduct().getSeller());oi.setQuantity(ci.getQuantity());oi.setPrice(ci.getProduct().getPrice());o.getItems().add(oi);total=total.add(ci.getProduct().getPrice().multiply(BigDecimal.valueOf(ci.getQuantity())));}o.setTotalAmount(total);o=orders.save(o);Payment p=new Payment();p.setOrder(o);p.setAmount(total);p.setStatus(Payment.Status.PENDING);payments.save(p);c.getItems().clear();carts.save(c);return Map.of("orderId",o.getId(),"amount",total,"status",o.getStatus());}
@GetMapping List<Order> mine(Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return orders.findByUserIdOrderByCreatedAtDesc(u.getId());}}
